def gen(rng):
    def fmt(qs):
        return str(len(qs)) + '\n' + '\n'.join(f'{s} {x}' for s, x in qs)
    tests = [fmt([(0, 0)]), fmt([(9, 5), (5, 6), (7, 4), (6, 0)]), fmt([(0, 0), (12, 4)]), fmt([(1, 1)]), fmt([(2, 0)]),
             fmt([(1, 0)]), fmt([(10**15, 10**15)]), fmt([(10**15, 0)]), fmt([(10**15, 1)]), fmt([(3, 3), (4, 4), (8, 2)])]
    # exhaustive small
    tests.append(fmt([(s, x) for s in range(0, 20) for x in range(0, 6)]))
    for _ in range(15):
        qs = []
        for _ in range(rng.randint(1, 12)):
            a = rng.randint(0, 60)
            b = rng.randint(0, 60)
            if rng.random() < 0.6:
                qs.append((a + b, a ^ b))
            else:
                qs.append((rng.randint(0, 100), rng.randint(0, 100)))
        tests.append(fmt(qs))
    def big(valid_prob):
        qs = []
        for _ in range(50000):
            r = rng.random()
            if r < valid_prob:
                a = rng.randint(0, 5 * 10**14)
                b = rng.randint(0, 5 * 10**14)
                qs.append((a + b, a ^ b))
            else:
                qs.append((rng.randint(0, 10**15), rng.randint(0, 10**15)))
        return fmt(qs)
    tests.append(big(1.0))
    tests.append(big(0.5))
    tests.append(big(0.0))
    qs = []
    for _ in range(50000):
        a = rng.randint(2**48, 5 * 10**14)
        b = rng.randint(2**48, 5 * 10**14)
        qs.append((a + b, a ^ b))
    tests.append(fmt(qs))
    return tests
